SELECT id, name, email, country, city, signup_date, is_active, credit_limit, age, COUNT(credit_limit) OVER (PARTITION BY segment ORDER BY age, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_credit_limit, SUM(credit_limit) OVER (PARTITION BY segment ORDER BY age, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_credit_limit, MIN(credit_limit) OVER (PARTITION BY segment ORDER BY age, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_credit_limit FROM customers;
